--
-- Name: vw_resumen_cuartel_diario; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_resumen_cuartel_diario AS
 SELECT r.fecha_enrolamiento,
    c.nombre_cuartel AS cuartel,
    count(*) AS total
   FROM (public.registro_enrolamiento r
     JOIN public.cuartel c ON ((c.id_cuartel = r.id_cuartel)))
  GROUP BY r.fecha_enrolamiento, c.nombre_cuartel;


ALTER VIEW public.vw_resumen_cuartel_diario OWNER TO postgres;

--
-- Name: vw_resumen_edad_diario; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_resumen_edad_diario AS
 SELECT fecha_enrolamiento,
        CASE
            WHEN es_mayor_edad THEN 'MAYOR DE EDAD'::text
            ELSE 'MENOR DE EDAD'::text
        END AS categoria,
    count(*) AS total
   FROM public.registro_enrolamiento
  GROUP BY fecha_enrolamiento, es_mayor_edad;


ALTER VIEW public.vw_resumen_edad_diario OWNER TO postgres;

--
-- Name: vw_resumen_equipo_diario; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_resumen_equipo_diario AS
 SELECT r.fecha_enrolamiento,
    e.tipo_equipo AS equipo,
    count(*) AS total
   FROM (public.registro_enrolamiento r
     JOIN public.equipo e ON ((e.id_equipo = r.id_equipo)))
  GROUP BY r.fecha_enrolamiento, e.tipo_equipo;


ALTER VIEW public.vw_resumen_equipo_diario OWNER TO postgres;

--
-- Name: vw_resumen_estado_diario; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_resumen_estado_diario AS
 SELECT r.fecha_enrolamiento,
    'SINCRONIZACION'::text AS tipo_estado,
    ep.descripcion,
    count(*) AS total
   FROM (public.registro_enrolamiento r
     JOIN public.estado_proceso ep ON ((ep.id_estado = r.id_estado_sincronizacion)))
  GROUP BY r.fecha_enrolamiento, ep.descripcion
UNION ALL
 SELECT r.fecha_enrolamiento,
    'REGISTRO'::text AS tipo_estado,
    ep.descripcion,
    count(*) AS total
   FROM (public.registro_enrolamiento r
     JOIN public.estado_proceso ep ON ((ep.id_estado = r.id_estado_registro)))
  GROUP BY r.fecha_enrolamiento, ep.descripcion
UNION ALL
 SELECT r.fecha_enrolamiento,
    'GENERAL'::text AS tipo_estado,
    ep.descripcion,
    count(*) AS total
   FROM (public.registro_enrolamiento r
     JOIN public.estado_proceso ep ON ((ep.id_estado = r.id_estado_general)))
  GROUP BY r.fecha_enrolamiento, ep.descripcion;


ALTER VIEW public.vw_resumen_estado_diario OWNER TO postgres;

